Notifications.Insert_Notification_001:
INSERT INTO
  public."Notifications"(
    "NotificationId",
    "PayloadHash",
    "UserId",
    "UserEmail",
    "Culture",
    "Operation",
    "Status",
    "ProductId",
    "ProductName",
    "ProductVersion",
    "ErrorCode",
    "CorrelationId",
    "OccurredAtUtc",
    "TraceParent",
    "TraceState",
    "DeliveryStatus")
VALUES(
    @NotificationId,
    @PayloadHash,
    @UserId,
    @UserEmail,
    @Culture,
    @Operation,
    @Status,
    @ProductId,
    @ProductName,
    @ProductVersion,
    @ErrorCode,
    @CorrelationId,
    @OccurredAtUtc,
    @TraceParent,
    @TraceState,
    'Pending')
ON CONFLICT
  ("NotificationId") DO NOTHING
RETURNING
  1;

Notifications.Select_Notification_002:
SELECT COALESCE(MAX("SequenceNumber"), 0) FROM public."Notifications" WHERE "UserId" = @UserId AND "CreatedAtUtc" >= @CutoffUtc;
SELECT COUNT(*) FROM public."Notifications" WHERE "UserId" = @UserId AND "CreatedAtUtc" >= @CutoffUtc AND "ReadAtUtc" IS NULL;
SELECT "NotificationId", "SequenceNumber", "Operation", "Status", "ProductId", "ProductName", "ProductVersion", "OccurredAtUtc", "ErrorCode", "DeliveryStatus", "DeliveredAtUtc", "ReadAtUtc" FROM public."Notifications" WHERE "UserId" = @UserId AND "CreatedAtUtc" >= @CutoffUtc AND (@BeforeSequence IS NULL OR "SequenceNumber" < @BeforeSequence) ORDER BY "SequenceNumber" DESC LIMIT @Take;
